package com.nthexperience.desktop;

import java.util.*;
import org.json.*;

/** Klondike and FreeCell rules; every move is validated before changing the deal. */
final class XpCards {
    static final int FOUNDATION=100,CELL=200,WASTE=300,STOCK=400;
    final boolean freecell;final List<List<Integer>> tableau=new ArrayList<>(),foundations=new ArrayList<>(),cells=new ArrayList<>();final List<Integer> stock=new ArrayList<>(),waste=new ArrayList<>();final boolean[] face=new boolean[52];final ArrayDeque<String> history=new ArrayDeque<>();int draw=1,moves;
    XpCards(boolean freecell,long seed){this.freecell=freecell;for(int i=0;i<(freecell?8:7);i++)tableau.add(new ArrayList<>());for(int i=0;i<4;i++){foundations.add(new ArrayList<>());cells.add(new ArrayList<>());}List<Integer> deck=new ArrayList<>();for(int i=0;i<52;i++)deck.add(i);Collections.shuffle(deck,new Random(seed));if(freecell){for(int i=0;i<52;i++){int card=deck.get(i);tableau.get(i%8).add(card);face[card]=true;}}else{for(int col=0;col<7;col++){for(int row=0;row<=col;row++)tableau.get(col).add(deck.remove(deck.size()-1));face[last(tableau.get(col))]=true;}stock.addAll(deck);}}
    static int rank(int card){return card%13+1;}static int suit(int card){return card/13;}static boolean red(int card){return suit(card)==1||suit(card)==3;}static int last(List<Integer> pile){return pile.isEmpty()?-1:pile.get(pile.size()-1);}
    static String name(int card){if(card<0)return "Empty";String rank=rank(card)==1?"A":rank(card)==11?"J":rank(card)==12?"Q":rank(card)==13?"K":String.valueOf(rank(card));return rank+new String[]{"♠","♥","♣","♦"}[suit(card)];}
    List<Integer> pile(int id){if(id>=0&&id<tableau.size())return tableau.get(id);if(id>=FOUNDATION&&id<FOUNDATION+4)return foundations.get(id-FOUNDATION);if(id>=CELL&&id<CELL+4)return cells.get(id-CELL);if(id==WASTE)return waste;if(id==STOCK)return stock;throw new IllegalArgumentException("Invalid pile");}
    private void remember(){try{history.addLast(state().toString());while(history.size()>100)history.removeFirst();}catch(JSONException impossible){throw new IllegalStateException(impossible);}}
    void drawStock(){if(freecell)return;remember();if(stock.isEmpty()){while(!waste.isEmpty()){int card=waste.remove(waste.size()-1);face[card]=false;stock.add(card);}}else for(int i=0;i<draw&&!stock.isEmpty();i++){int card=stock.remove(stock.size()-1);face[card]=true;waste.add(card);}moves++;}
    boolean valid(int from,int index,int to){
        if(from==to||from==STOCK||to==STOCK||to==WASTE)return false;List<Integer> source,target;try{source=pile(from);target=pile(to);}catch(IllegalArgumentException invalid){return false;}if(index<0||index>=source.size())return false;int card=source.get(index),count=source.size()-index;if(!face[card])return false;
        if(from>=FOUNDATION&&from<FOUNDATION+4&&freecell)return false;if(from>=FOUNDATION&&count!=1)return false;
        for(int i=index+1;i<source.size();i++)if(!face[source.get(i)]||red(source.get(i-1))==red(source.get(i))||rank(source.get(i-1))!=rank(source.get(i))+1)return false;
        if(to>=FOUNDATION&&to<FOUNDATION+4)return count==1&&suit(card)==to-FOUNDATION&&rank(card)==target.size()+1;
        if(to>=CELL&&to<CELL+4)return freecell&&count==1&&target.isEmpty();
        if(to<0||to>=tableau.size())return false;if(target.isEmpty()){if(!freecell&&rank(card)!=13)return false;}else{int top=last(target);if(!face[top]||red(top)==red(card)||rank(top)!=rank(card)+1)return false;}
        if(freecell&&count>1){int emptyCells=0,emptyColumns=0;for(List<Integer> cell:cells)if(cell.isEmpty())emptyCells++;for(int i=0;i<tableau.size();i++)if(i!=to&&i!=from&&tableau.get(i).isEmpty())emptyColumns++;if(count>(emptyCells+1)*(1<<emptyColumns))return false;}return true;
    }
    boolean move(int from,int index,int to){if(!valid(from,index,to))return false;remember();List<Integer> source=pile(from),target=pile(to);target.addAll(new ArrayList<>(source.subList(index,source.size())));source.subList(index,source.size()).clear();if(from>=0&&from<tableau.size()&&!source.isEmpty())face[last(source)]=true;moves++;return true;}
    boolean autoFoundation(int from,int index){List<Integer> p;try{p=pile(from);}catch(Exception e){return false;}return index>=0&&index<p.size()&&move(from,index,FOUNDATION+suit(p.get(index)));}
    boolean won(){int n=0;for(List<Integer> p:foundations)n+=p.size();return n==52;}
    boolean undo(){if(history.isEmpty())return false;try{XpCards saved=restore(history.removeLast());copy(saved);return true;}catch(JSONException e){return false;}}
    private void copy(XpCards other){for(int i=0;i<tableau.size();i++){tableau.get(i).clear();tableau.get(i).addAll(other.tableau.get(i));}for(int i=0;i<4;i++){foundations.get(i).clear();foundations.get(i).addAll(other.foundations.get(i));cells.get(i).clear();cells.get(i).addAll(other.cells.get(i));}stock.clear();stock.addAll(other.stock);waste.clear();waste.addAll(other.waste);System.arraycopy(other.face,0,face,0,52);draw=other.draw;moves=other.moves;}
    String hint(){List<Integer> sources=new ArrayList<>();for(int i=0;i<tableau.size();i++)sources.add(i);if(freecell)for(int i=0;i<4;i++)sources.add(CELL+i);else sources.add(WASTE);for(int from:sources){List<Integer> source=pile(from);for(int at=0;at<source.size();at++){int card=source.get(at);if(!face[card])continue;if(valid(from,at,FOUNDATION+suit(card)))return "Move "+name(card)+" to its foundation";for(int to=0;to<tableau.size();to++)if(valid(from,at,to)&&!(at==0&&tableau.get(to).isEmpty()))return "Move "+name(card)+" to column "+(to+1);}}if(!freecell&&(!stock.isEmpty()||!waste.isEmpty()))return "Draw or recycle the stock";return freecell?"Try moving one top card into a free cell":"No useful move found; Undo or deal a new game";}
    JSONObject state()throws JSONException{JSONArray table=new JSONArray(),base=new JSONArray(),free=new JSONArray();for(List<Integer> p:tableau)table.put(new JSONArray(p));for(List<Integer> p:foundations)base.put(new JSONArray(p));for(List<Integer> p:cells)free.put(new JSONArray(p));StringBuilder shown=new StringBuilder();for(boolean f:face)shown.append(f?'1':'0');return new JSONObject().put("freecell",freecell).put("tableau",table).put("foundations",base).put("cells",free).put("stock",new JSONArray(stock)).put("waste",new JSONArray(waste)).put("face",shown).put("draw",draw).put("moves",moves);}
    static XpCards restore(String json)throws JSONException{if(json.length()>12000)throw new JSONException("Deal too large");JSONObject v=new JSONObject(json);XpCards game=new XpCards(v.getBoolean("freecell"),0);Set<Integer> seen=new HashSet<>();JSONArray table=v.getJSONArray("tableau"),found=v.getJSONArray("foundations"),free=v.getJSONArray("cells");if(table.length()!=game.tableau.size()||found.length()!=4||free.length()!=4)throw new JSONException("Invalid piles");for(int i=0;i<table.length();i++)load(game.tableau.get(i),table.getJSONArray(i),seen);for(int i=0;i<4;i++){load(game.foundations.get(i),found.getJSONArray(i),seen);load(game.cells.get(i),free.getJSONArray(i),seen);if(game.cells.get(i).size()>1)throw new JSONException("Invalid cell");for(int n=0;n<game.foundations.get(i).size();n++)if(game.foundations.get(i).get(n)!=i*13+n)throw new JSONException("Invalid foundation");}load(game.stock,v.getJSONArray("stock"),seen);load(game.waste,v.getJSONArray("waste"),seen);if(seen.size()!=52)throw new JSONException("Incomplete deck");String face=v.getString("face");if(!face.matches("[01]{52}"))throw new JSONException("Invalid face states");for(int i=0;i<52;i++)game.face[i]=face.charAt(i)=='1';game.draw=v.getInt("draw");if(game.draw!=1&&game.draw!=3)throw new JSONException("Invalid draw count");game.moves=Math.max(0,v.optInt("moves"));if(game.freecell&&(!game.stock.isEmpty()||!game.waste.isEmpty()))throw new JSONException("Invalid FreeCell stock");return game;}
    private static void load(List<Integer> out,JSONArray data,Set<Integer> seen)throws JSONException{out.clear();for(int i=0;i<data.length();i++){int card=data.getInt(i);if(card<0||card>=52||!seen.add(card))throw new JSONException("Invalid or repeated card");out.add(card);}}
}
